345	// Re-adding an existing gset element creates the op but does not move the
346	// union, so no frame is sent; genuinely new elements push the sorted union.
347	func TestCRDTSubscribeGSetDuplicateElementIsSilent(t *testing.T) {
348		srv, _ := newWSTestServer(t)
