366		if code := postCRDTOps(t, srv, "doc", crdtGSetBody("dev-1", crdtGSetOp("g2", "apple"))); code != http.StatusOK {
367			t.Fatalf("duplicate-element submit = %d", code)
368		}
369		conn.setReadDeadline(300 * time.Millisecond)
370		if _, _, _, ok := conn.readFrameMaybe(); ok {
371			t.Fatal("re-adding an existing element pushed a frame")
372		}
373		conn.clearReadDeadline()
374	
375		// A mixed batch (one old, one new) pushes once with the grown union.
376		if code := postCRDTOps(t, srv, "doc", crdtGSetBody("dev-1", crdtGSetOp("g3", "apple", "cherry"))); code != http.StatusOK {
377			t.Fatalf("mixed submit = %d", code)
