379		state = conn.readCRDTState()
380		if got := crdtSetElements(t, state); len(got) != 3 || got[0] != "apple" || got[1] != "banana" || got[2] != "cherry" {
381			t.Fatalf("elements = %v, want [apple banana cherry]", got)
382		}
