// contributes a distinct tag and the derived membership is stable regardless
// of arrival order.
func TestCRDTORSetConcurrentAddsConverge(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	devices := make([]string, 6)
	for i := range devices {
		devices[i] = fmt.Sprintf("dev-%d", i)
	}
