	}
	close(start)
	wg.Wait()

	if got := orsetState(t, s, "doc"); len(got) != len(devices) {
		t.Fatalf("elements = %v, want %d distinct", got, len(devices))
	}
	// Re-deriving the merge never changes the answer.
	if got := orsetState(t, s, "doc"); len(got) != len(devices) {
		t.Fatalf("second read = %v", got)
