		{"empty ops", `{"deviceId":"dev-1","type":"orset","ops":[]}`},
		{"dup op ids", `{"deviceId":"dev-1","type":"orset","ops":[{"id":"a","action":"add","elements":["x"]},{"id":"a","action":"add","elements":["y"]}]}`},
