87	// Re-posting the same id is idempotent only with the same device, action and
88	// element set; any mismatch is a 409 that leaves the membership untouched.
89	func TestCRDTORSetIdempotencyAndConflict(t *testing.T) {
90		h, _ := newTestHandler(t)
91		registerDevice(t, h, "dev-1")
92		registerDevice(t, h, "dev-2")
93	
94		if w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtORSetBody("dev-1",
95			crdtORSetAddOp("g1", "banana", "apple"))); w.Code != http.StatusOK {
96			t.Fatal(w.Body.String())
97		}
98		// Identical content, elements reordered: idempotent created=false.
99		w, body := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtORSetBody("dev-1",
100			crdtORSetAddOp("g1", "apple", "banana")))
101		if w.Code != http.StatusOK {
102			t.Fatal(w.Body.String())
103		}
104		if body["results"].([]any)[0].(map[string]any)["created"].(bool) {
105			t.Fatal("identical repeat must be created=false")
106		}
107		// Different elements -> 409.
108		if w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtORSetBody("dev-1",
109			crdtORSetAddOp("g1", "apple", "cherry"))); w.Code != http.StatusConflict {
110			t.Fatalf("different elements = %d, want 409", w.Code)
111		}
112		// Add vs remove -> 409.
113		if w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtORSetBody("dev-1",
114			crdtORSetRemoveOp("g1", "banana", "apple"))); w.Code != http.StatusConflict {
115			t.Fatalf("different action = %d, want 409", w.Code)
116		}
117		// Different device -> 409.
118		if w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtORSetBody("dev-2",
119			crdtORSetAddOp("g1", "banana", "apple"))); w.Code != http.StatusConflict {
120			t.Fatalf("cross-device repeat = %d, want 409", w.Code)
121		}
122	
123		w, state := doRequest(t, h, http.MethodGet, "/v1/documents/doc/crdt/state")
124		if w.Code != http.StatusOK || state["type"] != "orset" {
125			t.Fatalf("%d %s", w.Code, w.Body.String())
126		}
127		got := state["value"].([]any)
128		if len(got) != 2 || got[0] != "apple" || got[1] != "banana" {
129			t.Fatalf("elements after conflicts = %v", got)
130		}
131	}
